function t(key, params){
  const entry = STRINGS[key];
  let s = entry ? (entry[cfg.lang] || entry.en || entry.tr) : null;
  if(s==null) return key;
  if(params) for(const k in params) s = s.split('{'+k+'}').join(params[k]);
  return s;
}
function applyLanguage(){
  document.documentElement.lang = cfg.lang;
  document.querySelectorAll('[data-i18n]').forEach(el=>{ el.textContent = t(el.dataset.i18n); });
  document.querySelectorAll('[data-i18n-html]').forEach(el=>{ el.innerHTML = t(el.dataset.i18nHtml); });
  if(typeof refreshAllDynamicUI==='function') refreshAllDynamicUI();
  syncLangDockButton();
}
function syncLangDockButton(){
  const el=document.getElementById('langFlagIcon'); if(el) el.innerHTML = flagSvg(cfg.lang);
  document.querySelectorAll('.langCard').forEach(c=>c.classList.toggle('sel', c.dataset.code===cfg.lang));
}
// Bayrak/dil ızgarasını bir kez kurar (bootstrap'te main.js'den çağrılır) —
// kartların kendisi dilden bağımsız (her zaman kendi native adını gösterir),
// bu yüzden dil değişince yeniden kurulmasına gerek yok, sadece .sel sınıfı
// syncLangDockButton() ile güncellenir.
function renderLangGrid(){
  const grid=document.getElementById('langGrid'); if(!grid) return;
  grid.innerHTML='';
  LANGUAGES.forEach(l=>{
    const d=document.createElement('div');
    d.className='langCard'+(cfg.lang===l.code?' sel':'');
    d.dataset.code=l.code;
    d.innerHTML=`<div class="langFlag">${flagSvg(l.code)}</div><div class="langName">${l.native}</div>`;
    d.addEventListener('click', ()=>{ setLanguage(l.code); if(typeof beep==='function') beep(500,0.06,'sine',0.1); });
    grid.appendChild(d);
  });
}
function setLanguage(code){
  if(!LANGUAGES.find(l=>l.code===code)) return;
  cfg.lang = code; saveCfg(); applyLanguage();
}
// Mod isimlerini (leaderboard satırlarında MODE_LABEL yerine) t() üzerinden
// döndürür — shop-ui.js'deki renderLeaderboard() bunu kullanır.
function modeLabel(m){ return t('mode_'+m+'_name') || m; }
// Dil değiştiğinde, halihazırda kurulmuş (innerHTML ile bir kez yazılmış)
// dinamik ekranları güncel dilde yeniden çizer. Hepsi zaten idempotent
// render fonksiyonları (tekrar tekrar çağrılabilir) — sadece var olan
// DOM elemanlarını günceller, hangi ekran açık olursa olsun sorunsuz.
function refreshAllDynamicUI(){
  if(typeof renderThemeGrid==='function') renderThemeGrid();
  if(typeof renderSkins==='function') renderSkins();
  if(typeof syncSettings==='function') syncSettings();
  if(typeof syncShopIfOpen==='function') syncShopIfOpen();
  if(typeof renderDealBanner==='function') renderDealBanner();
  if(typeof syncAdButtons==='function') syncAdButtons();
  if(typeof renderUpgrades==='function' && typeof state!=='undefined' && state==='upgrades'){ renderUpgrades(); renderUpgradesTab(); }
  if(typeof renderBattlepass==='function' && typeof state!=='undefined' && state==='battlepass') renderBattlepass();
  if(typeof syncStats==='function' && typeof state!=='undefined' && state==='stats') syncStats();
  if(typeof refreshDailyStatus==='function' && typeof state!=='undefined' && state==='mode') refreshDailyStatus();
  if(typeof renderBoostRow==='function' && typeof state!=='undefined' && state==='mode') renderBoostRow();
  if(typeof goMenu==='function' && typeof state!=='undefined' && state==='menu') goMenu();
}
